  "mind_probe": {"name":"Mind Probe","type":"Mana","range":"T","duration":"Sustained","drain":2,"category":"Detection","combat_type":"Force ","damage":"","notes":"Active, directional\nDV (F÷2) + 2\nSee table; target aware of probing; one piece of information per Complex Action; further uses within hours = target's Willpower: −2 dice per previous attempt.\nSR4A p.203-211"},
  "antidote": {"name":"Antidote","type":"Mana","range":"T","duration":"Permanent","drain":"","category":"Health","combat_type":"Force ","damage":"","notes":"DV (Toxin DV) − 2\nBefore the toxin does damage; + net hits dice on the Toxin Resistance Test (after the fact the GM may allow easing side effects).\nSR4A p.203-211"},
