  "decrease_attribute_negative": {"name":"Decrease [Attribute] (negative)","type":"Physical","range":"T","duration":"Sustained","drain":1,"category":"Health","combat_type":"Force ","damage":"","notes":"DV (F÷2) + 1\nOne version per Physical and Mental attribute (not Special: Initiative, Edge, Essence, Magic, Resonance); affects natural and augmented attributes; target resists with the attribute affected; reduce by net hits; 0 Physical = paralyzed, 0 Mental = mindless; derived stats change (e.g. Intuition affects Initiative; Willpower removes Stun boxes).\nSR4A p.203-211"},
