  "heal": {"name":"Heal","type":"Mana","range":"T","duration":"Permanent","drain":"","category":"Health","combat_type":"Force ","damage":"","notes":"DV (Damage Value) − 2\nHeals hits boxes of Physical damage; hits can instead shave 1 Combat Turn each off the time to become permanent. Only once per set of injuries.\nSR4A p.203-211"},
