  "ignite": {"name":"Ignite","type":"Physical","range":"LOS","duration":"Permanent","drain":0,"category":"Manipulation","combat_type":"Force ","damage":"","notes":"Physical\nDV F÷2\nCatches fire when permanent; objects: net hits ≥ Object Resistance; living: opposed vs. Body (+Counterspelling): Force boxes of Fire damage on turn 1, +1 per turn, resisted with Body + half Impact armor; may detonate ammo/explosives.\nSR4A p.203-211"},
