  "levitate": {"name":"Levitate","type":"Physical","range":"LOS","duration":"Sustained","drain":1,"category":"Manipulation","combat_type":"Force ","damage":"","notes":"Physical\nDV (F÷2) + 1\nThreshold = 1 per 200 kg; movement rate = Force × net hits m/turn; opposed vs. holder's Strength + Body (spell Force × 2) to take an object away; unwilling living being: target's Strength + Body; self-levitation allowed; flung objects: Ranged Attack, Stun damage set by the GM.\nSR4A p.203-211"},
