  "petrify": {"name":"Petrify","type":"Physical","range":"LOS","duration":"Sustained","drain":2,"category":"Manipulation","combat_type":"Force ","damage":"","notes":"Physical\nDV (F÷2) + 2\nOpposed vs. Body (+Counterspelling); Force ≥ target Body; living tissue only; target unconscious; barrier Armor = Body + net hits.\nSR4A p.203-211"},
  "physical_barrier": {"name":"Physical Barrier","type":"Physical","range":"LOS (A)","duration":"Sustained","drain":3,"category":"Manipulation","combat_type":"Force ","damage":"","notes":"Environmental, area\nDV (F÷2) + 3\nForce-field wall/dome with 1 Armor and 1 Structure per hit; dome radius/height = normal radius or wall height/length = Force; regenerates damage at the start of each turn; collapses if penetrated; not on the astral plane; molecule-sized things pass; −1 visibility penalty through it.\nSR4A p.203-211"},
